function tone(kind){try{ctx??=new(window.AudioContext||window.webkitAudioContext)();ctx.resume();const a=kind==='finish'?[392,523,659,784,1046]:kind==='bad'?[440,392]:[523,659,784];a.forEach((f,i)=>{const o=ctx.createOscillator(),g=ctx.createGain(),t=ctx.currentTime+i*.13;o.type='triangle';o.frequency.value=f;g.gain.setValueAtTime(.0001,t);g.gain.exponentialRampToValueAtTime(.014,t+.025);g.gain.exponentialRampToValueAtTime(.0001,t+.22);o.connect(g).connect(ctx.destination);o.start(t);o.stop(t+.23)})}catch{}}
