function paint(){stage.innerHTML='';const big=document.createElement('div');big.className='scene';big.textContent=q.view;const detail=document.createElement('div');detail.className='detail';detail.textContent=q.detail;stage.append(big,detail);choices.innerHTML='';q.options.forEach(x=>{const b=document.createElement('button');b.className='choice';b.textContent=x;b.setAttribute('aria-label',name(x));b.onclick=()=>choose(x);choices.append(b)});progress.textContent=(round+1)+' / 3'+(q.sequence||q.steps>1?' ⭐ '+step+' / '+(q.sequence?.length||q.steps):'')}
