async function choose(x){if(busy)return;busy=true;if(x!==q.answer){tone('bad');await speak('これは '+name(x)+' だね。 もういちど。 '+q.prompt);busy=false;return}tone('ok');stage.firstChild.textContent='🌟 '+game[3]+' 🌟';if(q.sequence&&step<q.sequence.length-1){step++;q.answer=q.sequence[step];q.prompt='つぎは '+name(q.answer)+'だよ。 '+name(q.answer)+'を おしてね';paint();await speak(q.prompt);busy=false;return}if(q.steps>1&&step<q.steps-1){step++;stage.firstChild.textContent='🎈 ⬆️ '+'⭐'.repeat(step)+' ⚖️'.repeat(q.steps-step);progress.textContent=(round+1)+' / 3 ⭐ '+step+' / '+q.steps;await speak('いいね。 あと '+(q.steps-step)+'こ。 はずすを おしてね');busy=false;return}await speak('せいかい！ '+game[1]+' できたね');round++;if(round<3){await wait(150);await begin()}else finish()}
